-- Source: schema_updates_v2.sql

CREATE TYPE leave_status AS ENUM ('pending', 'approved', 'rejected');
CREATE TYPE syllabus_status AS ENUM ('not_started', 'in_progress', 'completed');
CREATE TYPE task_status AS ENUM ('todo', 'in_progress', 'done');


-- ═══════════════════════════════════════════════════
-- SECTION 2: HELPER FUNCTIONS
-- ═══════════════════════════════════════════════════

-- 2a. Admin check (bypasses RLS via SECURITY DEFINER)
-- Source: supabase_setup.sql
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'admin'
  );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- 2b. Approval check (bypasses RLS to prevent infinite recursion)
-- Source: fix_profiles_rls.sql
CREATE OR REPLACE FUNCTION public.is_user_approved()
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND (status = 'approved' OR role = 'admin')
  );
END;
$$;

-- 2c. Auto-create profile on signup (latest version from schema_updates_v4.sql)
-- Supersedes: supabase_setup.sql, schema_approvals.sql, fix_profiles.sql,
--             remove_approval_requirement.sql, schema_updates_v3.sql
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, name, email, role, status, subject, staff_type)
  VALUES (
    NEW.id,
    COALESCE(NEW.raw_user_meta_data->>'full_name', 'Unknown User'),
    NEW.email,
    CASE WHEN NEW.email = 'admin@bgs.edu' THEN 'admin' ELSE 'teacher' END,
    'approved',
    NEW.raw_user_meta_data->>'subject',
    COALESCE(NEW.raw_user_meta_data->>'staff_type', 'teaching')
  );
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 2d. Generic updated_at trigger function
-- Source: supabase_setup.sql
CREATE OR REPLACE FUNCTION public.handle_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 2e. Alternative updated_at (UTC-explicit, used by attendance module)
-- Source: attendance_setup.sql
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = timezone('utc'::text, now());
    RETURN NEW;
END;
$$ LANGUAGE 'plpgsql';

-- 2f. Column protection: prevents non-admins from changing role/status
-- Source: schema_approvals.sql
CREATE OR REPLACE FUNCTION public.protect_profile_columns()
RETURNS TRIGGER AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND role = 'admin') THEN
        NEW.role = OLD.role;
        NEW.status = OLD.status;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- ═══════════════════════════════════════════════════
-- SECTION 3: TABLES — Auth & Identity (Central Person Model)
-- ═══════════════════════════════════════════════════
-- Target Model Source: 202607251000_create_persons_employees.sql
-- Legacy Model Source: supabase_setup.sql + schema_approvals.sql

-- 3a. Central Identity (persons)
CREATE TABLE public.persons (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,
    first_name TEXT NOT NULL,
    last_name TEXT NOT NULL DEFAULT '',
    email TEXT,
    phone TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 3b. Employee Sub-profile (employees)
CREATE TABLE public.employees (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    person_id UUID NOT NULL UNIQUE REFERENCES public.persons(id) ON DELETE CASCADE,
    role TEXT NOT NULL DEFAULT 'teacher' CHECK (role IN ('teacher', 'admin')),
    status TEXT NOT NULL DEFAULT 'approved' CHECK (status IN ('pending', 'approved', 'rejected')),
    subject TEXT,
    department TEXT,
    staff_type TEXT DEFAULT 'teaching',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 3c. Legacy Profiles (DEPRECATED, read-only fallback)
-- Retained during Spec 02 identity migration for backward compatibility / dual-write fallback.
CREATE TABLE public.profiles (
    id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    phone TEXT,
    role TEXT NOT NULL DEFAULT 'teacher' CHECK (role IN ('teacher', 'admin')),
    status TEXT NOT NULL DEFAULT 'approved' CHECK (status IN ('pending', 'approved', 'rejected')),
    subject TEXT,
    department TEXT,
    staff_type TEXT DEFAULT 'teaching',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ═══════════════════════════════════════════════════
-- SECTION 4: TABLES — Weekly Reports
-- ═══════════════════════════════════════════════════
-- Source: supabase_setup.sql

CREATE TABLE public.weekly_reports (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,

    -- Report Metadata
    report_date DATE NOT NULL,
    subject TEXT,
    status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'submitted')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    submitted_at TIMESTAMPTZ,

    -- 1. Last Week Section
    topics_covered TEXT,
    is_on_schedule BOOLEAN DEFAULT true,
    challenges TEXT,

    -- 2. CET Section
    skip_cet BOOLEAN DEFAULT false,
    cet_book TEXT,
    cet_questions JSONB DEFAULT '[]'::jsonb,
    cet_tests JSONB DEFAULT '[]'::jsonb,
    cet_doubt JSONB DEFAULT '[]'::jsonb,

    -- 3. NEET Section
    skip_neet BOOLEAN DEFAULT false,
    neet_book TEXT,
    neet_questions JSONB DEFAULT '[]'::jsonb,
    neet_tests JSONB DEFAULT '[]'::jsonb,
    neet_doubt JSONB DEFAULT '[]'::jsonb,

    -- 4. JEE Section
    skip_jee BOOLEAN DEFAULT false,
    jee_book TEXT,
    jee_questions JSONB DEFAULT '[]'::jsonb,
    jee_tests JSONB DEFAULT '[]'::jsonb,
    jee_doubt JSONB DEFAULT '[]'::jsonb,

    UNIQUE(user_id, report_date)
);


