    title TEXT NOT NULL,
    body TEXT,
    posted_by TEXT NOT NULL DEFAULT 'Admin',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ═══════════════════════════════════════════════════
-- SECTION 6: TABLES — Marks Module
-- ═══════════════════════════════════════════════════
-- Source: marks_setup.sql + fix_duplicates.sql

-- 6a. Students (legacy flat model — the table the app actively uses)
-- NOTE: schema_updates_v5_foundation.sql defines a DIFFERENT students table
--       with person_id FK to persons. That is the Spec 02 target, not this.
CREATE TABLE public.students (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    stream TEXT NOT NULL CHECK (stream IN ('Science', 'Commerce')),
    year TEXT NOT NULL CHECK (year IN ('1st Year', '2nd Year')),
    class TEXT NOT NULL,
    roll_number INT,
    parent_phone TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT unique_student_batch UNIQUE (stream, year, class, roll_number)
);

-- 6b. Tests
CREATE TABLE public.tests (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    stream TEXT NOT NULL CHECK (stream IN ('Science', 'Commerce')),
    year TEXT NOT NULL CHECK (year IN ('1st Year', '2nd Year')),
    class TEXT NOT NULL,
    subjects JSONB NOT NULL DEFAULT '[]'::jsonb,
    created_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE(name, stream, year, class)
);

-- 6c. Mark Entries
CREATE TABLE public.mark_entries (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    test_id UUID NOT NULL REFERENCES public.tests(id) ON DELETE CASCADE,
    student_id UUID NOT NULL REFERENCES public.students(id) ON DELETE CASCADE,
    marks JSONB NOT NULL DEFAULT '{}'::jsonb,
    is_absent BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE(test_id, student_id)
);


-- ═══════════════════════════════════════════════════
-- SECTION 7: TABLES — Attendance Module
-- ═══════════════════════════════════════════════════
-- Source: attendance_setup.sql

CREATE TABLE public.attendance_sessions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    stream TEXT NOT NULL CHECK (stream IN ('Science', 'Commerce')),
    year TEXT NOT NULL CHECK (year IN ('1st Year', '2nd Year')),
    class TEXT NOT NULL,
    date DATE NOT NULL,
    created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
    UNIQUE(stream, year, class, date)
);

CREATE TABLE public.attendance_records (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id UUID REFERENCES public.attendance_sessions(id) ON DELETE CASCADE,
    student_id UUID REFERENCES public.students(id) ON DELETE CASCADE,
    is_absent BOOLEAN DEFAULT FALSE,
    remarks TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
    UNIQUE(session_id, student_id)
);


