-- SECTION 14: RLS POLICIES
-- ═══════════════════════════════════════════════════

-- ─── 14a. Profiles ───
-- Source: fix_profiles_rls.sql (replaces earlier recursive policy)
CREATE POLICY "Allow users to read own profile and approved users to read all"
ON public.profiles FOR SELECT USING (
    auth.uid() = id OR public.is_user_approved()
);

-- Source: schema_approvals.sql
CREATE POLICY "Users can update own profile or admins can update any"
ON public.profiles FOR UPDATE
USING (
    auth.uid() = id OR
    EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.role = 'admin')
);

-- ─── 14b. Weekly Reports ───
-- Source: supabase_setup.sql
CREATE POLICY "Users can view their own reports" ON public.weekly_reports
    FOR SELECT USING (auth.uid() = user_id);

CREATE POLICY "Users can insert their own reports" ON public.weekly_reports
    FOR INSERT WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update their own reports" ON public.weekly_reports
    FOR UPDATE USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "Admins can view all reports" ON public.weekly_reports;
DROP POLICY IF EXISTS "Users can view their own reports or admins can view all" ON public.weekly_reports;
CREATE POLICY "Users can view their own reports or admins can view all" ON public.weekly_reports
    FOR SELECT USING (auth.uid() = user_id OR public.is_admin());

-- ─── 14c. Announcements ───
-- Source: supabase_setup.sql
CREATE POLICY "Anyone can view announcements" ON public.announcements
    FOR SELECT USING (true);

CREATE POLICY "Admins can insert announcements" ON public.announcements
    FOR INSERT WITH CHECK (public.is_admin());

CREATE POLICY "Admins can delete announcements" ON public.announcements
    FOR DELETE USING (public.is_admin());

-- ─── 14d. Students ───
-- Source: marks_setup.sql
CREATE POLICY "Authenticated users can view students" ON public.students
    FOR SELECT USING (auth.uid() IS NOT NULL);

CREATE POLICY "Admins can manage students" ON public.students
    FOR ALL USING (public.is_admin());

CREATE POLICY "Teachers can insert students" ON public.students
    FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);

-- ─── 14e. Tests ───
-- Source: marks_setup.sql
CREATE POLICY "Authenticated users can view tests" ON public.tests
    FOR SELECT USING (auth.uid() IS NOT NULL);

CREATE POLICY "Authenticated users can create tests" ON public.tests
    FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);

CREATE POLICY "Authenticated users can update tests" ON public.tests
    FOR UPDATE USING (auth.uid() IS NOT NULL);

CREATE POLICY "Authenticated users can delete tests" ON public.tests
    FOR DELETE USING (auth.uid() IS NOT NULL);

-- ─── 14f. Mark Entries ───
-- Source: marks_setup.sql
CREATE POLICY "Authenticated users can view mark_entries" ON public.mark_entries
    FOR SELECT USING (auth.uid() IS NOT NULL);

CREATE POLICY "Authenticated users can insert mark_entries" ON public.mark_entries
    FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);

CREATE POLICY "Authenticated users can update mark_entries" ON public.mark_entries
    FOR UPDATE USING (auth.uid() IS NOT NULL);

CREATE POLICY "Authenticated users can delete mark_entries" ON public.mark_entries
    FOR DELETE USING (auth.uid() IS NOT NULL);

-- ─── 14g. Attendance Sessions ───
-- Source: attendance_setup.sql
CREATE POLICY "Allow authenticated users to select attendance sessions"
ON public.attendance_sessions FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "Allow authenticated users to insert attendance sessions"
ON public.attendance_sessions FOR INSERT WITH CHECK (auth.role() = 'authenticated');

CREATE POLICY "Allow authenticated users to update attendance sessions"
ON public.attendance_sessions FOR UPDATE USING (auth.role() = 'authenticated');

-- ─── 14h. Attendance Records ───
-- Source: attendance_setup.sql
CREATE POLICY "Allow authenticated users to select attendance records"
ON public.attendance_records FOR SELECT USING (auth.role() = 'authenticated');

CREATE POLICY "Allow authenticated users to insert attendance records"
ON public.attendance_records FOR INSERT WITH CHECK (auth.role() = 'authenticated');

CREATE POLICY "Allow authenticated users to update attendance records"
ON public.attendance_records FOR UPDATE USING (auth.role() = 'authenticated');

-- ─── 14i. Meetings ───
-- Source: meetings_setup.sql
CREATE POLICY "Admins have full access to meetings" ON public.meetings
    FOR ALL USING (public.is_admin());

CREATE POLICY "Teachers can view targeted meetings" ON public.meetings
    FOR SELECT USING (
        audience_type = 'all_staff' OR
        (audience_type = 'department' AND department = (SELECT p.department FROM public.profiles p WHERE p.id = auth.uid())) OR
        (audience_type = 'individual' AND id IN (SELECT ma.meeting_id FROM public.meeting_attendees ma WHERE ma.teacher_id = auth.uid()))
    );

-- ─── 14j. Meeting Attendees ───
-- Source: meetings_setup.sql
CREATE POLICY "Admins have full access to meeting_attendees" ON public.meeting_attendees
    FOR ALL USING (public.is_admin());

CREATE POLICY "Teachers can view meeting attendees" ON public.meeting_attendees
    FOR SELECT USING (TRUE);

